import os, json, re, yaml

agents_dir = os.path.expanduser('~/.config/opencode/agents')
registry_dir = os.path.expanduser('~/.config/opencode/registry')

agents = []
for fname in sorted(os.listdir(agents_dir)):
    if not fname.endswith('.md'):
        continue
    fpath = os.path.join(agents_dir, fname)
    name = fname.replace('.md', '')

    with open(fpath) as f:
        content = f.read()

    # Parse YAML frontmatter
    fm = {}
    if content.startswith('---'):
        parts = content.split('---', 2)
        if len(parts) >= 2:
            try:
                fm = yaml.safe_load(parts[1]) or {}
            except:
                fm = {}

    desc = fm.get('description', '')
    mode = fm.get('mode', 'subagent')
    model = fm.get('model', '')
    color = fm.get('color', '')
    temperature = fm.get('temperature', None)
    permissions = fm.get('permission', {})

    # Infer capabilities from description
    desc_lower = desc.lower()
    capabilities = []
    if 'research' in desc_lower or 'researches' in desc_lower:
        capabilities.append('research')
    if 'plan' in desc_lower or 'planner' in desc_lower:
        capabilities.append('planning')
    if 'execut' in desc_lower:
        capabilities.append('execution')
    if 'review' in desc_lower or 'audit' in desc_lower:
        capabilities.append('review')
    if 'code' in desc_lower:
        capabilities.append('code-analysis')
    if 'debug' in desc_lower:
        capabilities.append('debugging')
    if 'doc' in desc_lower or 'document' in desc_lower:
        capabilities.append('documentation')
    if 'security' in desc_lower:
        capabilities.append('security')
    if 'ui' in desc_lower:
        capabilities.append('ui-design')
    if 'eval' in desc_lower:
        capabilities.append('evaluation')
    if 'classif' in desc_lower:
        capabilities.append('classification')
    if 'synthes' in desc_lower:
        capabilities.append('synthesis')
    if 'verif' in desc_lower:
        capabilities.append('verification')
    if 'mem' in desc_lower:
        capabilities.append('memory')
    if 'revers' in desc_lower:
        capabilities.append('reverse-engineering')
    if 'integrat' in desc_lower:
        capabilities.append('integration')
    if 'intel' in desc_lower:
        capabilities.append('intelligence')
    if 'pattern' in desc_lower:
        capabilities.append('pattern-mapping')
    if 'framework' in desc_lower or 'select' in desc_lower:
        capabilities.append('framework-selection')
    if 'assumpt' in desc_lower:
        capabilities.append('assumptions-analysis')
    if 'domain' in desc_lower:
        capabilities.append('domain-research')
    if 'nyquist' in desc_lower:
        capabilities.append('validation')
    if 'superpow' in desc_lower:
        capabilities.append('superpowers')
    if 'profiler' in desc_lower or 'profile' in desc_lower:
        capabilities.append('profiling')

    if not capabilities:
        capabilities.append('general')

    # Infer spawn source
    spawn_sources = []
    if 'spawned by' in desc_lower:
        spawn_match = re.search(r'spawned by (.*?)(?:\.|$)', desc, re.IGNORECASE)
        if spawn_match:
            spawn_sources.append(spawn_match.group(1).strip())

    agent = {
        'name': name,
        'description': desc,
        'mode': mode,
        'capabilities': list(set(capabilities)),
        'spawn_sources': spawn_sources
    }

    if model:
        agent['model'] = model
    if color:
        agent['color'] = color
    if temperature is not None:
        agent['temperature'] = temperature
    if permissions:
        agent['permissions'] = {
            k: v for k, v in permissions.items()
        }

    agents.append(agent)

# Build registry
registry = {
    'version': '1.0.0',
    'created': '2026-07-19',
    'description': 'AgentRegistry Central — GSD Agent Discovery and Capability Routing',
    'total_agents': len(agents),
    'agents': agents,
    'capability_index': {}
}

# Build capability index
for agent in agents:
    for cap in agent['capabilities']:
        registry['capability_index'].setdefault(cap, [])
        registry['capability_index'][cap].append(agent['name'])

# Save registry
with open(os.path.join(registry_dir, 'agent-registry.json'), 'w') as f:
    json.dump(registry, f, indent=2, ensure_ascii=False)

print(f"✅ AgentRegistry criado: {len(agents)} agentes indexados")
print(f"\n📊 Distribuição por capability:")
for cap in sorted(registry['capability_index'].keys()):
    print(f"  {cap}: {len(registry['capability_index'][cap])} agentes")

# Save capability index separately
cap_index = registry['capability_index']
with open(os.path.join(registry_dir, 'capability-index.json'), 'w') as f:
    json.dump(cap_index, f, indent=2, ensure_ascii=False)

print(f"\n✅ CapabilityIndex criado: {len(cap_index)} capabilities")
