import json, os

registry_dir = os.path.expanduser('~/.config/opencode/registry')

# Load registry
with open(os.path.join(registry_dir, 'agent-registry.json')) as f:
    registry = json.load(f)

# =============================================
# EventBus — Central Event System
# =============================================
event_bus = {
    "version": "1.0.0",
    "description": "EventBus Central — desacoplamento entre agentes, comandos, hooks e MCPs",
    "topics": {
        "agent:registered": {
            "description": "Um novo agente foi registrado no Registry",
            "producers": ["agent-registry"],
            "consumers": ["*"]
        },
        "agent:capability:updated": {
            "description": "Capacidade de um agente foi alterada",
            "producers": ["agent-registry"],
            "consumers": ["capability-router", "context-broker"]
        },
        "agent:health:changed": {
            "description": "Status de saúde de um agente mudou",
            "producers": ["agent-monitor"],
            "consumers": ["capability-router", "dashboard"]
        },
        "workflow:phase:started": {
            "description": "Uma fase de workflow foi iniciada",
            "producers": ["gsd-executor"],
            "consumers": ["context-broker", "otel-exporter", "dashboard"]
        },
        "workflow:phase:completed": {
            "description": "Uma fase de workflow foi concluída",
            "producers": ["gsd-executor"],
            "consumers": ["context-broker", "otel-exporter", "dashboard", "memory-keeper"]
        },
        "workflow:phase:failed": {
            "description": "Uma fase de workflow falhou",
            "producers": ["gsd-executor"],
            "consumers": ["context-broker", "otel-exporter", "dashboard", "auto-healer"]
        },
        "hook:executed": {
            "description": "Um hook foi executado",
            "producers": ["hook-registry"],
            "consumers": ["otel-exporter", "session-activity-tracker"]
        },
        "command:invoked": {
            "description": "Um comando GSD foi invocado",
            "producers": ["command-router"],
            "consumers": ["context-broker", "otel-exporter"]
        },
        "mcp:health:changed": {
            "description": "Status de saúde de um MCP mudou",
            "producers": ["mcp-health-check"],
            "consumers": ["capability-router", "dashboard"]
        },
        "context:propagated": {
            "description": "Contexto (TraceID) foi propagado",
            "producers": ["context-broker"],
            "consumers": ["*"]
        },
        "registry:synced": {
            "description": "Registry foi sincronizado após alteração",
            "producers": ["agent-registry"],
            "consumers": ["capability-router", "context-broker", "dashboard"]
        }
    },
    "total_topics": 11
}

with open(os.path.join(registry_dir, 'event-bus.json'), 'w') as f:
    json.dump(event_bus, f, indent=2)

print(f"✅ EventBus criado: {event_bus['total_topics']} tópicos")

# =============================================
# ContextBroker + TraceID — Unified Context
# =============================================
context_broker = {
    "version": "1.0.0",
    "description": "ContextBroker — Contexto unificado com TraceID global",
    "trace_id": {
        "format": "ulid",
        "propagation": "W3C TraceContext (traceparent header)",
        "inject_on": ["command:invoked", "agent:spawned", "hook:executed", "mcp:called"]
    },
    "components": {
        "command": {
            "trace": True,
            "fields": ["trace_id", "command_name", "args", "timestamp", "duration_ms"]
        },
        "agent": {
            "trace": True,
            "fields": ["trace_id", "agent_name", "capability", "parent_trace_id", "timestamp", "duration_ms", "status"]
        },
        "hook": {
            "trace": True,
            "fields": ["trace_id", "hook_id", "phase", "timestamp", "duration_ms", "exit_code"]
        },
        "mcp": {
            "trace": True,
            "fields": ["trace_id", "server_name", "tool_name", "timestamp", "duration_ms", "status"]
        }
    },
    "memory_unification": {
        "strategy": "context-broker como ponte entre ck sessions e mempalace",
        "ck_integration": "TraceID vincula sessions do ck com chamadas de agente",
        "mempalace_integration": "TraceID permite replay de decisões arquiteturais"
    },
    "benefits": [
        "menos acoplamento entre componentes",
        "rastreabilidade de ponta a ponta",
        "debugging distribuído",
        "base para OpenTelemetry"
    ]
}

with open(os.path.join(registry_dir, 'context-broker.json'), 'w') as f:
    json.dump(context_broker, f, indent=2)

print(f"✅ ContextBroker criado: TraceID global + {len(context_broker['components'])} componentes rastreáveis")

# =============================================
# Capability Router — Dynamic Agent Routing
# =============================================
cap_rules = []
for agent in registry['agents']:
    for cap in agent['capabilities']:
        cap_rules.append({
            "capability": cap,
            "agent": agent['name'],
            "priority": 1,
            "active": True
        })

capability_router = {
    "version": "1.0.0",
    "description": "Capability Router — Roteamento dinâmico por capacidade, não por nome",
    "strategy": "round-robin",
    "fallback_strategy": "failover",
    "rules": cap_rules,
    "total_rules": len(cap_rules)
}

with open(os.path.join(registry_dir, 'capability-router.json'), 'w') as f:
    json.dump(capability_router, f, indent=2)

print(f"✅ CapabilityRouter criado: {len(cap_rules)} regras de roteamento ({len(registry['capability_index'])} capacidades)")

print(f"\n📦 Registry completo:")
for fname in ['agent-registry.json', 'capability-index.json', 'capability-router.json', 'event-bus.json', 'context-broker.json']:
    fpath = os.path.join(registry_dir, fname)
    size = os.path.getsize(fpath)
    print(f"  {fname} ({size:,} bytes)")
