            continue

        fm = parse_frontmatter(skill_path)
        desc = fm.get('description', '')
        caps = infer_capabilities(desc)

        skill_entry = {
            'name': skill_name,
            'description': desc,
            'mode': fm.get('mode', 'skill'),
