        for fname in os.listdir(COMMANDS_DIR):
            if fname.endswith('.md'):
                name = fname.replace('.md', '')
                fm = parse_frontmatter(os.path.join(COMMANDS_DIR, fname))
                cmds[name] = {
                    'name': name,
                    'description': fm.get('description', ''),
                    'argument_hint': fm.get('argument-hint', ''),
                }
    return cmds

