                                'description': trigger.get('description', ''),
                            }
        except:
            pass
    return hooks

# ─── Build Registry ─────────────────────────────────────────────────
def build_registry():
    existing = read_json(os.path.join(REGISTRY_DIR, 'agent-registry.json'))
    agents_list = existing.get('agents', [])

