        log("Nenhuma alteração detectada.")
    return changed

# ─── Watch mode ─────────────────────────────────────────────────────
def watch_mode():
    """Monitora alterações nos diretórios e sincroniza automaticamente."""
    import time
    log("Modo observador ativo. Pressione Ctrl+C para parar.")

    last_checksums = {}
    dirs_to_watch = [AGENTS_DIR, SKILLS_DIR, COMMANDS_DIR, os.path.dirname(CONFIG_FILE)]

    try:
        while True:
            changed = False
            for d in dirs_to_watch:
                if not os.path.isdir(d):
                    continue
                current = {}
                for root, dirs, files in os.walk(d):
                    for f in files:
                        if f.endswith(('.md', '.json')):
                            fpath = os.path.join(root, f)
                            current[fpath] = hash_file(fpath)

                if current != last_checksums.get(d, {}):
                    changed = True
                    last_checksums[d] = current

            if changed:
                log("Alteração detectada, sincronizando...")
                build_registry()
            time.sleep(5)
    except KeyboardInterrupt:
        log("Observador parado.")

# ─── Main ───────────────────────────────────────────────────────────
if __name__ == '__main__':
    if '--watch' in sys.argv:
        # Primeiro sync, depois watch
        build_registry()
        watch_mode()
    else:
        build_registry()

