                'priority': 1,
                'active': True,
            })

    # Sync commands, MCPs, hooks
    commands = sync_commands()
    mcps = sync_mcps()
    hooks = sync_hooks()

    # ── Write registry files ──
    registry = {
        'version': '1.0.0',
        'last_sync': datetime.now().isoformat(),
        'total_agents': len([a for a in agents_list if a.get('source') in ('agent', 'skill')]),
        'total_skills': len([a for a in agents_list if a.get('source') == 'skill']),
        'total_commands': len(commands),
        'total_mcps': len(mcps),
        'total_hooks': len(hooks),
        'agents': agents_list,
        'capability_index': cap_index,
        'commands': commands,
        'mcps': mcps,
        'hooks': hooks,
    }

    r1 = write_json(os.path.join(REGISTRY_DIR, 'agent-registry.json'), registry)
    r2 = write_json(os.path.join(REGISTRY_DIR, 'capability-index.json'), cap_index)
    r3 = write_json(os.path.join(REGISTRY_DIR, 'capability-router.json'), {'version': '1.0.0', 'rules': cap_rules, 'total_rules': len(cap_rules)})

    # Update EventBus with current topics
    event_bus = read_json(os.path.join(REGISTRY_DIR, 'event-bus.json'))
    if event_bus:
        # Add agent-specific topics dynamically
        for agent in agents_list:
            topic = f"agent:{agent['name']}:invoked"
            if topic not in {t for t in event_bus.get('topics', {})}:
                event_bus['topics'][topic] = {
                    'description': f"Agente {agent['name']} foi invocado",
                    'producers': ['capability-router'],
                    'consumers': ['context-broker', 'otel-exporter']
                }
    r4 = write_json(os.path.join(REGISTRY_DIR, 'event-bus.json'), event_bus or {})

    changed = r1 or r2 or r3 or r4

    log(f"Sync concluído: {registry['total_agents']} agentes | {len(commands)} comandos | {len(mcps)} MCPs | {len(hooks)} hooks")
    if not changed:
        log("Nenhuma alteração detectada.")
    return changed

# ─── Watch mode ─────────────────────────────────────────────────────
def watch_mode():
    """Monitora alterações nos diretórios e sincroniza automaticamente."""
    import time
    log("Modo observador ativo. Pressione Ctrl+C para parar.")

    last_checksums = {}
    dirs_to_watch = [AGENTS_DIR, SKILLS_DIR, COMMANDS_DIR, os.path.dirname(CONFIG_FILE)]

    try:
        while True:
            changed = False
            for d in dirs_to_watch:
                if not os.path.isdir(d):
                    continue
                current = {}
                for root, dirs, files in os.walk(d):
                    for f in files:
                        if f.endswith(('.md', '.json')):
                            fpath = os.path.join(root, f)
                            current[fpath] = hash_file(fpath)

                if current != last_checksums.get(d, {}):
                    changed = True
                    last_checksums[d] = current

            if changed:
                log("Alteração detectada, sincronizando...")
                build_registry()
            time.sleep(5)
    except KeyboardInterrupt:
        log("Observador parado.")

# ─── Main ───────────────────────────────────────────────────────────
if __name__ == '__main__':
    if '--watch' in sys.argv:
        # Primeiro sync, depois watch
        build_registry()
        watch_mode()
    else:
        build_registry()

