#!/usr/bin/env python3
"""
generate-dag-viewer.py — Gera DAG Viewer HTML com dados embutidos

Lê o AgentRegistry e gera um HTML autossuficiente com o grafo
interativo embutido (D3.js via CDN).
"""

import json, os, base64

REGISTRY_DIR = os.path.expanduser('~/.config/opencode/registry')
OUTPUT_FILE  = os.path.join(REGISTRY_DIR, 'dag-viewer.html')

def load_registry():
    path = os.path.join(REGISTRY_DIR, 'agent-registry.json')
    with open(path) as f:
        return json.load(f)

def generate(data):
    agents = data.get('agents', [])
    commands = list(data.get('commands', {}).values())
    mcps = list(data.get('mcps', {}).values())
    hooks = list(data.get('hooks', {}).values())

    # Build nodes and links as JSON data to embed
    nodes = []
    links = []

    # Agents
    for a in agents:
        nodes.append({
            'id': a['name'],
            'group': a.get('source', 'agent'),
            'label': a['name'],
            'desc': a.get('description', '')[:120],
            'caps': a.get('capabilities', []),
        })

    # Commands → agents (same prefix linkage)
    for c in commands:
        cname = c['name']
        nodes.append({
            'id': cname,
            'group': 'command',
            'label': cname,
            'desc': c.get('description', '')[:120],
            'caps': [],
        })

    # MCPs
    for m in mcps:
        nodes.append({
            'id': f"mcp:{m['name']}",
            'group': 'mcp',
            'label': m['name'],
            'desc': f"{m.get('type','?')} | {m.get('url','')[:80]}",
            'caps': [],
        })

    # Hooks (grouped by phase)
    phases = {}
    for h in hooks:
        phases.setdefault(h['phase'], []).append(h)

    for phase, hks in phases.items():
        phase_id = f"phase:{phase}"
        nodes.append({
            'id': phase_id,
            'group': 'hook',
            'label': phase,
            'desc': f"{len(hks)} hooks",
            'caps': [],
            'is_phase': True,
        })
        for h in hks:
            hid = f"hook:{h['id']}"
            nodes.append({
                'id': hid,
                'group': 'hook',
                'label': h.get('id', '?')[:35],
                'desc': h.get('description', '')[:100],
                'caps': [],
                'parent': phase_id,
            })
            links.append({'source': hid, 'target': phase_id})

    # Connect agents with same-prefix commands
    for c in commands:
        cname = c['name']
        for a in agents:
            aname = a['name']
            if aname.replace('gsd-', '') == cname.replace('gsd-', ''):
                links.append({'source': cname, 'target': aname})

    graph_data = json.dumps({'nodes': nodes, 'links': links})

    html = f'''<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>DAG Viewer — AgentRegistry</title>
<script src="https://d3js.org/d3.v7.min.js"></script>
<style>
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #0d1117; color: #c9d1d9; overflow: hidden; }}
  #toolbar {{ position: fixed; top: 0; left: 0; right: 0; height: 48px; background: #161b22; border-bottom: 1px solid #30363d; display: flex; align-items: center; padding: 0 16px; gap: 12px; z-index: 100; }}
  #toolbar h1 {{ font-size: 14px; font-weight: 600; color: #58a6ff; }}
  #toolbar .sep {{ width: 1px; height: 24px; background: #30363d; }}
  #toolbar span {{ font-size: 12px; color: #8b949e; }}
  #toolbar .badge {{ background: #21262d; padding: 2px 8px; border-radius: 12px; font-size: 11px; color: #8b949e; border: 1px solid #30363d; }}
  #toolbar button {{ background: #21262d; border: 1px solid #30363d; color: #c9d1d9; padding: 4px 12px; border-radius: 6px; cursor: pointer; font-size: 12px; }}
  #toolbar button:hover {{ background: #30363d; }}
  #toolbar input {{ background: #0d1117; border: 1px solid #30363d; color: #c9d1d9; padding: 4px 8px; border-radius: 6px; font-size: 12px; width: 180px; }}
  #toolbar input:focus {{ outline: none; border-color: #58a6ff; }}
  svg {{ width: 100%; height: calc(100vh - 48px); margin-top: 48px; }}
  .node circle {{ stroke-width: 2px; cursor: pointer; transition: r 0.2s; }}
  .node circle:hover {{ stroke: #58a6ff; }}
  .node text {{ font-size: 11px; fill: #c9d1d9; pointer-events: none; }}
  .link {{ stroke: #30363d; stroke-width: 1.5px; stroke-opacity: 0.6; }}
  .link:hover {{ stroke-opacity: 1; }}
  .legend {{ position: fixed; bottom: 16px; right: 16px; background: #161b22; border: 1px solid #30363d; border-radius: 8px; padding: 12px; font-size: 11px; z-index: 100; }}
  .legend-item {{ display: flex; align-items: center; gap: 8px; margin: 4px 0; }}
  .legend-dot {{ width: 10px; height: 10px; border-radius: 50%; border: 1px solid rgba(255,255,255,0.2); }}
  #detail {{ position: fixed; bottom: 16px; left: 16px; background: #161b22; border: 1px solid #30363d; border-radius: 8px; padding: 12px; font-size: 12px; max-width: 400px; display: none; z-index: 100; }}
  #detail h3 {{ color: #58a6ff; margin-bottom: 4px; }}
  #detail p {{ color: #8b949e; margin: 2px 0; }}
  #detail .tag {{ display: inline-block; background: #21262d; padding: 1px 6px; border-radius: 4px; margin: 2px; font-size: 10px; border: 1px solid #30363d; }}
</style>
</head>
<body>
<div id="toolbar">
  <h1>⊞ DAG Viewer</h1>
  <div class="sep"></div>
  <span>AgentRegistry</span>
  <span class="badge" id="count-nodes">0 nós</span>
  <span class="badge" id="count-links">0 conexões</span>
  <div class="sep"></div>
  <button onclick="resetZoom()">⟲ Centralizar</button>
  <button onclick="toggleLabels()">🏷 Labels</button>
  <div class="sep"></div>
  <input id="search" placeholder="🔍 Buscar..." oninput="filterNodes(this.value)">
</div>
<svg id="graph"></svg>
<div class="legend">
  <div class="legend-item"><div class="legend-dot" style="background:#58a6ff"></div> Agent</div>
  <div class="legend-item"><div class="legend-dot" style="background:#3fb950"></div> Skill</div>
  <div class="legend-item"><div class="legend-dot" style="background:#d29922"></div> Command</div>
  <div class="legend-item"><div class="legend-dot" style="background:#f85149"></div> MCP</div>
  <div class="legend-item"><div class="legend-dot" style="background:#bc8cff"></div> Hook</div>
</div>
<div id="detail"></div>
<script>
const COLORS = {{ agent: '#58a6ff', skill: '#3fb950', command: '#d29922', mcp: '#f85149', hook: '#bc8cff' }};
const DATA = {graph_data};

let showLabels = true, svg, g, sim, link, node, label;
const W = window.innerWidth, H = window.innerHeight - 48;

function init() {{
  const {{ nodes, links }} = DATA;
  document.getElementById('count-nodes').textContent = `${{nodes.length}} nós`;
  document.getElementById('count-links').textContent = `${{links.length}} conexões`;

  svg = d3.select('#graph');
  g = svg.append('g');
  svg.call(d3.zoom().scaleExtent([0.1,4]).on('zoom', e => g.attr('transform', e.transform)));

  sim = d3.forceSimulation(nodes)
    .force('link', d3.forceLink(links).id(d => d.id).distance(d => d.is_phase ? 50 : 100))
    .force('charge', d3.forceManyBody().strength(-250))
    .force('center', d3.forceCenter(W/2, H/2))
    .force('collision', d3.forceCollide(25));

  link = g.append('g').selectAll('line').data(links).join('line')
    .attr('class', 'link').attr('stroke', '#30363d');

  const drag = d3.drag()
    .on('start', (e,d) => {{ if(!e.active) sim.alphaTarget(0.3).restart(); d.fx=d.x; d.fy=d.y; }})
    .on('drag', (e,d) => {{ d.fx=e.x; d.fy=e.y; }})
    .on('end', (e,d) => {{ if(!e.active) sim.alphaTarget(0); d.fx=null; d.fy=null; }});

  node = g.append('g').selectAll('circle').data(nodes).join('circle')
    .attr('r', d => d.is_phase ? 10 : (d.group==='hook'&&!d.is_phase?5:7))
    .attr('fill', d => COLORS[d.group] || '#666')
    .attr('stroke', d => d3.color(COLORS[d.group]||'#666').darker(0.5))
    .call(drag)
    .on('click', (e,d) => showDetail(d))
    .on('mouseover', function(d) {{ d3.select(this).attr('r', d.is_phase?14:10); }})
    .on('mouseout', function(d) {{ d3.select(this).attr('r', d.is_phase?10:(d.group==='hook'&&!d.is_phase?5:7)); }});

  label = g.append('g').selectAll('text').data(nodes).join('text')
    .attr('dy', -12).attr('text-anchor', 'middle').attr('fill', '#c9d1d9').attr('font-size', '10px')
    .text(d => d.label);

  sim.on('tick', () => {{
    link.attr('x1',d=>d.source.x).attr('y1',d=>d.source.y).attr('x2',d=>d.target.x).attr('y2',d=>d.target.y);
    node.attr('cx',d=>d.x).attr('cy',d=>d.y);
    label.attr('x',d=>d.x).attr('y',d=>d.y);
  }});
}}

function showDetail(d) {{
  const el = document.getElementById('detail');
  el.style.display = 'block';
  el.innerHTML = `<h3>${{d.label}}</h3><p>${{d.desc||'Sem descrição'}}</p>
    ${{d.caps?.length ? '<p>'+d.caps.map(c=>'<span class=tag>'+c+'</span>').join('')+'</p>' : ''}}
    <p style="color:#8b949e;font-size:10px;margin-top:4px">Tipo: ${{d.group}}</p>`;
}}

function resetZoom() {{ svg.transition().duration(750).call(d3.zoom().transform, d3.zoomIdentity.translate(W/2,H/2).scale(0.6)); }}
function toggleLabels() {{ showLabels=!showLabels; label.attr('display', showLabels?'block':'none'); }}
function filterNodes(q) {{
  q = q.toLowerCase();
  node.attr('opacity', d => !q || d.label.toLowerCase().includes(q) ? 1 : 0.08);
  label.attr('opacity', d => !q || d.label.toLowerCase().includes(q) ? 1 : 0.08);
  link.attr('opacity', d => !q || (d.source.label?.toLowerCase().includes(q) || d.target.label?.toLowerCase().includes(q)) ? 0.6 : 0.03);
}}
document.addEventListener('click', e => {{ if(!e.target.closest('circle')&&!e.target.closest('#detail')) document.getElementById('detail').style.display='none'; }});
init();
</script></body></html>'''

    with open(OUTPUT_FILE, 'w') as f:
        f.write(html)

    print(f"✅ DAG Viewer gerado: {OUTPUT_FILE}")
    print(f"   Nós: {len(nodes)} | Conexões: {len(links)}")

if __name__ == '__main__':
    data = load_registry()
    generate(data)

