#!/usr/bin/env python3
"""
otel-span-emitter.py — Emite spans OTLP para o OpenTelemetry Collector

Uso:
  otel-span-emitter.py start <trace_id> <span_id> <parent_span_id> <name> [attrs...]
  otel-span-emitter.py end   <trace_id> <span_id> [status] [attrs...]

Exemplo:
  otel-span-emitter.py start "abc123" "span001" "" "agent:invoked" "agent.name=qwen3-coder" "category=coding"
  otel-span-emitter.py end   "abc123" "span001" "ok" "latency_ms=1234"

Variáveis de ambiente:
  OTEL_COLLECTOR_URL  (default: http://localhost:4318)
  OTEL_SERVICE_NAME   (default: gsd-agent-registry)
"""

import sys, os, json, time, uuid, hashlib
from urllib.request import Request, urlopen
from urllib.error import URLError

COLLECTOR_URL = os.environ.get("OTEL_COLLECTOR_URL", "http://localhost:4318")
SERVICE_NAME  = os.environ.get("OTEL_SERVICE_NAME", "gsd-agent-registry")

# Cache: guarda spans iniciados para cálculo de duração
_started_spans: dict = {}

def _b64(s: str) -> str:
    """Hex string → base64 (OTLP exige bytes codificados em base64)."""
    import base64
    raw = bytes.fromhex(s)
    return base64.b64encode(raw).decode()

def _now_ns() -> int:
    return time.time_ns()

def _make_span_id() -> str:
    return os.urandom(8).hex()

def _make_trace_id() -> str:
    return os.urandom(16).hex()


def cmd_start(trace_id: str, span_id: str, parent_span_id: str, name: str, attrs: list[str]):
    """Inicia um span e envia OTLP."""
    now = _now_ns()

    attributes = []
    for a in attrs:
        if "=" in a:
            k, v = a.split("=", 1)
            attributes.append({
                "key": k,
                "value": {"stringValue": v}
            })

    # Atributos fixos
    attributes.extend([
        {"key": "service.name", "value": {"stringValue": SERVICE_NAME}},
        {"key": "span.kind", "value": {"stringValue": "internal"}},
    ])

    # Se não tem parent, é root span
    if not parent_span_id:
        parent_span_id = "0000000000000000"

    payload = {
        "resourceSpans": [{
            "resource": {
                "attributes": [
                    {"key": "service.name", "value": {"stringValue": SERVICE_NAME}},
                    {"key": "telemetry.sdk.name", "value": {"stringValue": "opencode"}},
                    {"key": "telemetry.sdk.language", "value": {"stringValue": "python"}},
                ]
            },
            "scopeSpans": [{
                "scope": {"name": "gsd.hooks"},
                "spans": [{
                    "traceId": _b64(trace_id),
                    "spanId": _b64(span_id),
                    "parentSpanId": _b64(parent_span_id),
                    "name": name,
                    "kind": 1,  # SPAN_KIND_INTERNAL
                    "startTimeUnixNano": str(now),
                    "endTimeUnixNano": str(now),
                    "attributes": attributes,
                    "status": {"code": 0},  # STATUS_CODE_UNSET
                }]
            }]
        }]
    }

    _send(payload)
    _started_spans[span_id] = {"start": now, "trace_id": trace_id, "name": name}


def cmd_end(trace_id: str, span_id: str, status: str = "ok", attrs: list[str] = None):
    """Finaliza um span com duração calculada."""
    now = _now_ns()
    if attrs is None:
        attrs = []

    started = _started_spans.get(span_id, {"start": now - 1_000_000_000})  # fallback 1s
    start_time = started["start"]
    parent_trace = started.get("trace_id", trace_id)

    # Status code
    status_code = 1  # STATUS_CODE_OK
    status_msg = ""
    if status in ("error", "fail", "failed"):
        status_code = 2  # STATUS_CODE_ERROR
        status_msg = status
    elif status in ("unset", ""):
        status_code = 0

    attributes = [
        {"key": "service.name", "value": {"stringValue": SERVICE_NAME}},
        {"key": "span.kind", "value": {"stringValue": "internal"}},
        {"key": "duration_ms", "value": {"intValue": str((now - start_time) // 1_000_000)}},
    ]
    for a in (attrs or []):
        if "=" in a:
            k, v = a.split("=", 1)
            attributes.append({
                "key": k,
                "value": {"stringValue": v}
            })

    payload = {
        "resourceSpans": [{
            "resource": {
                "attributes": [
                    {"key": "service.name", "value": {"stringValue": SERVICE_NAME}},
                ]
            },
            "scopeSpans": [{
                "scope": {"name": "gsd.hooks"},
                "spans": [{
                    "traceId": _b64(parent_trace),
                    "spanId": _b64(span_id),
                    "name": started["name"],
                    "kind": 1,
                    "startTimeUnixNano": str(start_time),
                    "endTimeUnixNano": str(now),
                    "attributes": attributes,
                    "status": {"code": status_code, "message": status_msg},
                }]
            }]
        }]
    }

    _send(payload)
    if span_id in _started_spans:
        del _started_spans[span_id]


def cmd_event(trace_id: str, span_id: str, event_name: str, attrs: list[str] = None):
    """Adiciona um evento a um span existente."""
    now = _now_ns()
    attributes = []
    for a in (attrs or []):
        if "=" in a:
            k, v = a.split("=", 1)
            attributes.append({
                "key": k,
                "value": {"stringValue": v}
            })

    payload = {
        "resourceSpans": [{
            "resource": {
                "attributes": [
                    {"key": "service.name", "value": {"stringValue": SERVICE_NAME}},
                ]
            },
            "scopeSpans": [{
                "scope": {"name": "gsd.hooks"},
                "spans": [{
                    "traceId": _b64(trace_id),
                    "spanId": _b64(span_id),
                    "name": "event",
                    "kind": 1,
                    "startTimeUnixNano": str(now),
                    "endTimeUnixNano": str(now),
                    "events": [{
                        "timeUnixNano": str(now),
                        "name": event_name,
                        "attributes": attributes,
                    }],
                    "status": {"code": 0},
                }]
            }]
        }]
    }

    _send(payload)


def _send(payload: dict):
    """Envia payload OTLP via HTTP JSON."""
    url = f"{COLLECTOR_URL}/v1/traces"
    data = json.dumps(payload).encode()
    req = Request(url, data=data, method="POST")
    req.add_header("Content-Type", "application/json")
    try:
        resp = urlopen(req, timeout=2)
        resp.read()
    except URLError as e:
        # Silencia erros (hook não deve quebrar fluxo principal)
        debug = os.environ.get("OTEL_DEBUG", "")
        if debug:
            print(f"[otel] ERRO: {e}", file=sys.stderr)
    except Exception as e:
        debug = os.environ.get("OTEL_DEBUG", "")
        if debug:
            print(f"[otel] ERRO: {e}", file=sys.stderr)


def cmd_health():
    """Verifica se o collector está acessível."""
    try:
        url = f"{COLLECTOR_URL}/v1/traces"
        req = Request(url, data=b"{}", method="POST")
        req.add_header("Content-Type", "application/json")
        resp = urlopen(req, timeout=2)
        print(f"✅ Collector OK ({COLLECTOR_URL})")
        return True
    except Exception as e:
        print(f"❌ Collector indisponível: {e}")
        return False


def cmd_make_id(length=16):
    """Gera um trace_id (16 bytes = 32 hex) ou span_id (8 bytes = 16 hex)."""
    n = 16 if length == 16 else 8
    print(os.urandom(n).hex())


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(1)

    command = sys.argv[1]

    if command == "start":
        if len(sys.argv) < 5:
            print("Uso: otel-span-emitter.py start <trace_id> <span_id> <parent_span_id> <name> [attrs...]")
            sys.exit(1)
        cmd_start(sys.argv[2], sys.argv[3], sys.argv[4], sys.argv[5], sys.argv[6:])

    elif command == "end":
        if len(sys.argv) < 4:
            print("Uso: otel-span-emitter.py end <trace_id> <span_id> [status] [attrs...]")
            sys.exit(1)
        status = sys.argv[4] if len(sys.argv) > 4 else "ok"
        cmd_end(sys.argv[2], sys.argv[3], status, sys.argv[5:])

    elif command == "event":
        if len(sys.argv) < 5:
            print("Uso: otel-span-emitter.py event <trace_id> <span_id> <name> [attrs...]")
            sys.exit(1)
        cmd_event(sys.argv[2], sys.argv[3], sys.argv[4], sys.argv[5:])

    elif command == "health":
        cmd_health()

    elif command == "trace-id":
        print(os.urandom(16).hex())

    elif command == "span-id":
        print(os.urandom(8).hex())

    else:
        print(f"Comando desconhecido: {command}", file=sys.stderr)
        sys.exit(1)

