import json, base64

# OTLP HTTP JSON format (traces)
trace_id = bytes.fromhex('aabbccddee0011223344556677889900')
span_id = bytes.fromhex('1111111111111111')

payload = {
    'resourceSpans': [{
        'resource': {
            'attributes': [
                {'key': 'service.name', 'value': {'stringValue': 'gsd-agent-registry'}}
            ]
        },
        'scopeSpans': [{
            'scope': {'name': 'test'},
            'spans': [{
                'traceId': base64.b64encode(trace_id).decode(),
                'spanId': base64.b64encode(span_id).decode(),
                'name': 'manual:test',
                'kind': 2,
                'startTimeUnixNano': 1700000000000000000,
                'endTimeUnixNano': 1700000005000000000,
                'attributes': [
                    {'key': 'test', 'value': {'stringValue': 'true'}}
                ]
            }]
        }]
    }]
}

import urllib.request, urllib.error
req = urllib.request.Request(
    'http://localhost:4318/v1/traces',
    data=json.dumps(payload).encode(),
    headers={'Content-Type': 'application/json'}
)
try:
    resp = urllib.request.urlopen(req)
    print(f'Status: {resp.status}')
    print(f'Resposta: {resp.read().decode()}')
except urllib.error.HTTPError as e:
    print(f'HTTP Error: {e.code} {e.reason}')
    print(f'Body: {e.read().decode()}')
except Exception as e:
    print(f'Erro: {e}')
"

