payload = {
    "resourceSpans": [{
        "resource": {
            "attributes": [
                {"key": "service.name", "value": {"stringValue": "gsd-agent-registry"}}
            ]
        },
        "scopeSpans": [{
            "scope": {"name": "gsd.hooks"},
            "spans": [{
                "traceId": base64.b64encode(trace_id).decode(),
                "spanId": base64.b64encode(span_id).decode(),
                "name": "test:manual-payload",
                "kind": 1,
                "startTimeUnixNano": 1700000000000000000,
                "endTimeUnixNano": 1700000005000000000,
                "attributes": [
                    {"key": "foo", "value": {"stringValue": "bar"}}
                ],
                "status": {"code": 0}
            }]
        }]
    }]
}

data = json.dumps(payload).encode()
print("Payload size:", len(data))
print("Payload preview:", data[:200])

req = urllib.request.Request(
    "http://localhost:4318/v1/traces",
    data=data,
    headers={"Content-Type": "application/json"},
    method="POST"
)
try:
    resp = urllib.request.urlopen(req, timeout=3)
    print(f"Status: {resp.status} {resp.read().decode()}")
except urllib.error.HTTPError as e:
    print(f"HTTP Error: {e.code}")
    print(f"Response: {e.read().decode()[:200]}")
except Exception as e:
    print(f"Error: {e}")
