# O emitter usa str(now) para startTimeUnixNano
# OTLP espera int, não string!
# Vamos testar com valor correto
import json, base64, urllib.request, time

trace_id = bytes.fromhex("aabbccddee0011223344556677889900")
span_id = bytes.fromhex("1111111111111111")
now = time.time_ns()

# TESTE 1: startTime como string (o que o emitter faz)
payload_str = {
    "resourceSpans": [{
        "resource": {"attributes": [{"key": "service.name", "value": {"stringValue": "gsd-agent-registry"}}]},
        "scopeSpans": [{
            "scope": {"name": "gsd.hooks"},
            "spans": [{
                "traceId": base64.b64encode(trace_id).decode(),
                "spanId": base64.b64encode(span_id).decode(),
                "name": "test:string-time",
                "kind": 1,
                "startTimeUnixNano": str(now),  # STRING!
                "endTimeUnixNano": str(now),
                "status": {"code": 0}
            }]
        }]
    }]
}

req = urllib.request.Request(
    "http://localhost:4318/v1/traces",
    data=json.dumps(payload_str).encode(),
    headers={"Content-Type": "application/json"},
    method="POST"
)
try:
    resp = urllib.request.urlopen(req, timeout=3)
    print(f"String time: {resp.status} OK")
except urllib.error.HTTPError as e:
    print(f"String time: HTTP {e.code}")
    err = e.read().decode()[:300]
    print(f"  Error: {err}")

# TESTE 2: startTime como int (formato OTLP correto)
payload_int = {
    "resourceSpans": [{
        "resource": {"attributes": [{"key": "service.name", "value": {"stringValue": "gsd-agent-registry"}}]},
        "scopeSpans": [{
            "scope": {"name": "gsd.hooks"},
            "spans": [{
                "traceId": base64.b64encode(trace_id).decode(),
                "spanId": base64.b64encode(span_id).decode(),
                "name": "test:int-time",
                "kind": 1,
                "startTimeUnixNano": now,  # INT!
                "endTimeUnixNano": now,
                "status": {"code": 0}
            }]
        }]
    }]
}

req = urllib.request.Request(
    "http://localhost:4318/v1/traces",
    data=json.dumps(payload_int).encode(),
    headers={"Content-Type": "application/json"},
    method="POST"
)
try:
    resp = urllib.request.urlopen(req, timeout=3)
    print(f"Int time: {resp.status} OK")
except urllib.error.HTTPError as e:
    print(f"Int time: HTTP {e.code}")
    err = e.read().decode()[:300]
    print(f"  Error: {err}")
PYEOF

